-- +goose Up

CREATE TABLE IF NOT EXISTS government_filing (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    filing_id                uuid         NOT NULL,
    filing_key               semantic_key NOT NULL,
    authority_ref            text NOT NULL,
    report_definition_ref    text NOT NULL,
    period_ref               text NOT NULL,
    status                   text NOT NULL DEFAULT 'PREPARED',
    effective_from           date         NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, filing_id),
    CONSTRAINT government_filing_key_unique UNIQUE (tenant_id, filing_key),
    CONSTRAINT government_filing_status_check CHECK (status IN ('PREPARED', 'SUBMITTED', 'ACCEPTED', 'REJECTED', 'UNKNOWN', 'AMENDED')),
    CONSTRAINT government_filing_knowledge_order CHECK (known_at <= recorded_at)
);

CREATE INDEX IF NOT EXISTS government_filing_recorded
    ON government_filing (tenant_id, recorded_at DESC);

ALTER TABLE government_filing ENABLE ROW LEVEL SECURITY;
ALTER TABLE government_filing FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON government_filing
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON government_filing TO hcmnext_app;

CREATE TABLE IF NOT EXISTS filing_submission_attempt (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    attempt_id               uuid         NOT NULL,
    filing_id                uuid         NOT NULL,
    revision_sequence        bigint       NOT NULL,
    destination_ref          text NOT NULL,
    result                   text NOT NULL,
    idempotency_key          semantic_key NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, attempt_id),
    CONSTRAINT filing_submission_attempt_revision_positive CHECK (revision_sequence >= 1),
    CONSTRAINT filing_submission_attempt_knowledge_order CHECK (known_at <= recorded_at),
    FOREIGN KEY (tenant_id, filing_id) REFERENCES government_filing (tenant_id, filing_id)
);

CREATE INDEX IF NOT EXISTS filing_submission_attempt_recorded
    ON filing_submission_attempt (tenant_id, recorded_at DESC);

CREATE OR REPLACE TRIGGER filing_submission_attempt_append_only
    BEFORE UPDATE OR DELETE ON filing_submission_attempt
    FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

REVOKE UPDATE, DELETE ON filing_submission_attempt FROM PUBLIC;

ALTER TABLE filing_submission_attempt ENABLE ROW LEVEL SECURITY;
ALTER TABLE filing_submission_attempt FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON filing_submission_attempt
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT ON filing_submission_attempt TO hcmnext_app;

-- +goose Down
REVOKE ALL ON filing_submission_attempt FROM hcmnext_app;
